from pathlib import Path
import subprocess
r=Path.home()/'bplus-drop'; t=Path('/tmp/nearby110'); p=t/'com/bplus/share';p.mkdir(parents=True,exist_ok=True)
(p/'Store.java').write_text('''package com.bplus.share;import org.json.*;public class Store{public static final int PORT=47200;static JSONArray peers=new JSONArray();public static String get(String k,String d){return d;}public static String token(){return "receiver01234567";}public static JSONArray peers(){return peers;}public static void upsertPeer(JSONObject p){peers.put(p);}}''')
(p/'Profile.java').write_text('''package com.bplus.share;import org.json.*;public class Profile{public static JSONObject local()throws Exception{return new JSONObject().put("id","receiver").put("name","Receiver");}public static JSONObject clean(JSONObject p)throws Exception{return new JSONObject().put("id",p.getString("id")).put("name",p.optString("name"));}}''')
(p/'Net.java').write_text('''package com.bplus.share;import java.io.*;public class Net{public static String readAll(InputStream i)throws Exception{return "{}";}}''')
(t/'NearbyTests.java').write_text('''import com.bplus.share.*;import org.json.*;public class NearbyTests{
interface Fail{void run()throws Exception;}static int tests;static void check(boolean ok,String s)throws Exception{if(!ok)throw new Exception(s);System.out.println("PASS "+s);tests++;}static void denied(Fail f,String s)throws Exception{boolean no=false;try{f.run();}catch(java.io.IOException e){no=true;}check(no,s);}static JSONObject profile()throws Exception{return new JSONObject().put("id","sender").put("name","Sender");}
public static void main(String[] a)throws Exception{NearbyGate g=new NearbyGate();String sec="01234567890123456789012345678901";denied(()->g.request(profile(),"ip",sec,1000),"closed gate refuses requests");g.visible(true);NearbyGate.Request q=g.request(profile(),"ip",sec,1000);denied(()->g.get(q.id,"wrong","ip",1001),"request secret bound");denied(()->g.get(q.id,sec,"other",1001),"request IP bound");denied(()->g.request(profile(),"ip",sec,1001),"one pending per IP");g.decide(q.id,"declined",1002);denied(()->g.request(profile(),"ip",sec,1003),"per-IP cooldown");denied(()->g.get(q.id,sec,"ip",61001),"request expiry");NearbyGate.Request x=g.request(profile(),"ip",sec,62000);g.decide(x.id,"accepted",62001);g.cancel(x.id,sec,"ip",62002);check(x.status.equals("cancelled"),"accepted request can be cancelled before confirm");g.visible(false);denied(()->g.get(x.id,sec,"ip",62003),"closing gate clears requests");g.visible(true);NearbyGate.Request b=g.request(profile(),"ip2",sec,100000);g.decide(b.id,"blocked",100001);denied(()->g.request(profile(),"ip3",sec,100002),"blocked identity refused");
Nearby.gate.visible(true);JSONObject ad=Nearby.handle("/nearby/profile",new JSONObject(),"ip");check(!ad.has("token"),"visible discovery profile contains no token");JSONObject request=new JSONObject().put("profile",profile()).put("secret",sec);JSONObject response=Nearby.handle("/nearby/request",request,"ip");check(!response.has("token"),"request response contains no token");JSONObject auth=new JSONObject().put("request",response.getString("request")).put("secret",sec);check(!Nearby.handle("/nearby/status",auth,"ip").has("token"),"pending status exposes no token");auth.put("token","sender0123456789");denied(()->Nearby.handle("/nearby/confirm",auth,"ip"),"pre-acceptance confirm refused");check(Store.peers().length()==0,"pre-acceptance peer store unchanged");Nearby.gate.decide(response.getString("request"),"accepted",System.currentTimeMillis());check(Nearby.handle("/nearby/status",auth,"ip").has("token"),"token only after explicit acceptance");Nearby.handle("/nearby/confirm",auth,"ip");check(Store.peers().length()==1,"confirmation stores accepted peer");Nearby.gate.visible(false);denied(()->Nearby.handle("/nearby/profile",new JSONObject(),"ip"),"profile hidden after screen closes");System.out.println(tests+" assertions passed. JVM state/endpoint tests, not Android discovery or UI tests.");}}
''')
java=Path.home()/'jdk17/bin';cp='/tmp/org-json.jar'
subprocess.run([str(java/'javac'),'-cp',cp,'-d',str(t),*[str(x) for x in p.glob('*.java')],str(r/'app/src/com/bplus/share/Nearby.java'),str(r/'app/src/com/bplus/share/NearbyGate.java'),str(t/'NearbyTests.java')],check=True)
x=subprocess.run([str(java/'java'),'-cp',str(t)+':'+cp,'NearbyTests'],capture_output=True,text=True,check=True)
